begin;
select plan(26);
select has_table('app_private','customers','Clientes privados');
select has_table('app_private','loyalty_program_versions','Versiones de programa');
select has_table('app_private','loyalty_cards','Tarjetas');
select has_table('app_private','loyalty_events','Eventos inmutables');
select has_table('app_private','loyalty_rewards','Premios independientes');
select has_table('app_private','loyalty_incidents','Incidencias');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app_private' and c.relname in ('customers','loyalty_program_versions','loyalty_cards','loyalty_events','loyalty_rewards','loyalty_incidents') and c.relrowsecurity),6,'RLS en las seis tablas');
select ok(not has_schema_privilege('authenticated','app_private','usage'),'Esquema privado no expuesto');
select ok(not has_table_privilege('authenticated','app_private.customers','select'),'Cliente sin lectura directa');
select ok(not has_table_privilege('service_role','app_private.loyalty_cards','update'),'Sin modificación directa de tarjeta');
select ok(not has_function_privilege('authenticated','app_private.confirmed_phone(uuid)','execute'),'Puente de Auth interno');
select ok(not has_function_privilege('anon','public.get_my_card()','execute'),'Tarjeta requiere identidad');
select ok(not has_function_privilege('anon','public.credit_stamp(uuid,uuid,boolean,boolean,text)','execute'),'Anónimo sin sellos');
select ok(has_function_privilege('authenticated','public.credit_stamp(uuid,uuid,boolean,boolean,text)','execute'),'Sello valida personal dentro de RPC');
select has_column('app_private','customers','deleted_at','Borrado lógico de identidad');
select has_column('app_private','loyalty_rewards','deleted_by','Responsable de retiro');
select has_column('app_private','loyalty_incidents','delete_reason','Motivo obligatorio');
select hasnt_column('app_private','loyalty_events','deleted_at','Historial no se oculta');
select hasnt_column('app_private','customers','phone','Teléfono exclusivamente en Auth');
select is((select status from app_private.loyalty_program_versions where code='ten-visits-v1'),'draft','Programa comercial sin activar');
select ok((select reward_cost_cents is null and not reward_available from app_private.loyalty_program_versions where code='ten-visits-v1'),'Costo y stock sin inventar');
select throws_ok('update public.business_settings set loyalty_enabled=true where id=1','P0001','CONFIG_NOT_READY','No se habilita sin versión activa completa');
select ok(has_function_privilege('supabase_auth_admin','public.before_customer_created(jsonb)','execute'),'Solo Auth opera el filtro de altas');
select ok(not has_function_privilege('anon','public.before_customer_created(jsonb)','execute'),'Hook fuera de API pública');
select is(public.before_customer_created('{"user":{"phone":"51999000001","email":"","app_metadata":{"provider":"phone"}}}'::jsonb)->'error'->>'message','signup_disabled','Sin altas telefónicas públicas de Auth');
select is(public.before_customer_created('{"user":{"email":"synthetic@example.test","app_metadata":{"provider":"email"}}}'::jsonb)->'error'->>'message','signup_disabled','Correo público rechazado sin otorgar personal');
select * from finish();
rollback;
